<script setup>
import { Link, router } from '@inertiajs/vue3'; import AdminLayout from '../../../Layouts/AdminLayout.vue'; defineProps({posts:Object}); const remove=id=>confirm('Delete this post?')&&router.delete(`/admin/posts/${id}`);
</script>
<template><AdminLayout><div class="flex items-end justify-between"><div><p class="text-xs uppercase tracking-widest text-[#c56b4d]">JOURNAL</p><h1 class="mt-2 font-serif text-4xl">Blog posts</h1></div><Link href="/admin/posts/create" class="rounded-full bg-[#1d4843] px-5 py-3 text-sm font-semibold text-white">+ New post</Link></div><div class="mt-8 overflow-hidden rounded-2xl bg-white shadow-sm"><table class="w-full text-left text-sm"><thead class="bg-[#eef2ed] text-xs text-[#718079]"><tr><th class="px-5 py-4">Title</th><th class="px-5 py-4">Status</th><th class="px-5 py-4">Published</th><th></th></tr></thead><tbody class="divide-y divide-[#edf0eb]"><tr v-for="post in posts.data" :key="post.id"><td class="px-5 py-4 font-semibold">{{ post.title_bn }}</td><td class="px-5 py-4">{{ post.status }}</td><td class="px-5 py-4 text-[#718079]">{{ post.published_at || '—' }}</td><td class="px-5 py-4 text-right"><Link :href="`/admin/posts/${post.id}/edit`" class="mr-4 text-[#1d6a61]">Edit</Link><button @click="remove(post.id)" class="text-red-600">Delete</button></td></tr></tbody></table><p v-if="!posts.data?.length" class="p-10 text-center text-[#718079]">No posts yet.</p></div></AdminLayout></template>
